#!/usr/bin/env python3
"""Seed sweeps with a BOUNDARY-FREE score (CuPy + NVRTC; bgmt.cu is generated by make_bgmt.py from phpmt.cu).

Why: the dictionary score of phpmt counts dictionary words that sit exactly between the transcription's word separators. If LP2's
separators are independent of the plaintext words (its word lengths have no serial structure, results/analysis/wordlen_adjacency.txt, and with
LP2's separators imposed on English plaintext a planted seed scores 0 against 33, work/log/phase9_boundaries.md), that score cannot see a true
key. Here a decoded window is scored by the log-likelihood ratio of its plaintext under an English rune-bigram table; the skip / coin beam of
decode_fast is kept and pruned at every rune. A true key scores about +10 per rune (a wrong one about -12), so 120 runes separate them by far.

    python work/phpmt/bg.py sweep  <gen> <07|all> <lo> <hi> <out.tsv> [thr]
    python work/phpmt/bg.py verify <sweep.tsv> --gen <gen> [--top 10]     # whole-section decode of the best candidates (Rust key streams)
    python work/phpmt/bg.py table                                          # (re)write data/bigram.txt

gen: php glibc net py3 mt32 mt31 java msvc drand48 ruby (work/phpmt/src/gens.rs).
"""
import argparse
import os
import re
import subprocess
import sys
import tempfile
import time
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
WORK = HERE.parent
sys.path.insert(0, str(WORK))
os.environ.setdefault("CUPY_CACHE_DIR", str(HERE / "target" / "cupy_cache"))
import gpu_common  # noqa: E402
from gpu_common import NVRTC_OPTIONS  # noqa: E402

NR = 120                         # runes per window (keys available per seed: K = 160)
ABORT_AT, ABORT_THR = 40, 60      # give up after 40 runes unless the best path is above +60 (null maximum over 10^9 trials: ~+50; a true key is near +300)
HB, BLOCK = 64, 128
ROW = 128                        # runes per window row (BGROW in bgmt.cu)
CCAP = 1 << 20
TARGET_S = 0.3
TOPK = 4000
THR = 300                        # candidate floor (10 * ln-odds, 120 runes: a true key is near 1200)
K = 160
TABLE = HERE / "data" / "bigram.txt"
KERNEL = HERE / "bgmt.cu"
GENS = {"php": 0, "glibc": 1, "net": 2, "py3": 3, "mt32": 4, "mt31": 5, "java": 6, "msvc": 7, "drand48": 8, "ruby": 9}
EXE = "phpmt.exe" if os.name == "nt" else "phpmt"


# ------------------------------------------------------------------ the bigram table

def make_table():
    """round(10 ln(29 P(b|a))) from the Emerson text spelled in runes, word boundaries ignored; row 29 = unigram. Clipped to -40..+40."""
    import lp
    txt = (WORK / "ref" / "emerson_essays1.txt").read_text(encoding="utf-8")
    txt = txt[txt.index("SELF-RELIANCE"):].split("*** END OF")[0]
    stream = [r for w in re.findall(r"[A-Za-z]+", txt) for r in lp.word_to_key(w.upper().replace("IO", "IA"))]
    c = np.full((29, 29), 0.5)
    for a, b in zip(stream, stream[1:]):
        c[a, b] += 1
    p = c / c.sum(1, keepdims=True)
    u = np.bincount(stream, minlength=29) + 0.5
    u = u / u.sum()
    t = np.vstack([np.round(10 * np.log(29 * p)), np.round(10 * np.log(29 * u))[None, :]])
    return np.clip(t, -40, 40).astype(np.int16)


def load_table():
    if not TABLE.exists():
        TABLE.write_text("\n".join(" ".join(map(str, row)) for row in make_table()) + "\n", encoding="utf-8", newline="\n")
    return np.array([[int(x) for x in l.split()] for l in TABLE.read_text(encoding="utf-8").splitlines() if l.strip()], np.int16)


# ------------------------------------------------------------------ Python reference (mirrors bg_decode of bgmt.cu statement by statement)

def ref_decode(runes, prev, key, sign, atb, model, tbl, abort_at=None, abort_thr=None, keep_path=False):
    """returns (score, plaintext runes of the best path or None)"""
    key = [int(x) for x in key]
    Kk = len(key)
    sub = (lambda c, k: (c - k) % 29) if sign > 0 else (lambda c, k: (c + k) % 29)
    add = (lambda t, k: (t + k) % 29) if sign > 0 else (lambda t, k: (t - k) % 29)
    states = [(0, 0, 29, None)]                                    # score, j, last, path node (parent, plain)
    for i, c in enumerate(runes):
        pv = prev if i == 0 else int(runes[i - 1])
        nxt = []
        for score, j, last, node in states:
            if j + 3 >= Kk:
                continue

            def push(t, nj):
                if len(nxt) < 48:
                    p = 28 - t if atb else t
                    nxt.append((score + int(tbl[last, p]), nj, p, (node, p) if keep_path else None))

            k0 = key[j]
            if model == 0:
                push(sub(c, k0), j + 1)
                if pv >= 0:
                    t1 = sub(c, key[j + 1])
                    if add(t1, k0) == pv:
                        push(t1, j + 2)
                    t2 = sub(c, key[j + 2])
                    if add(t2, k0) == pv and add(t2, key[j + 1]) == pv:
                        push(t2, j + 3)
            else:
                if pv >= 0 and c == pv:
                    push(sub(c, k0), j + 2)
                else:
                    push(sub(c, k0), j + 1)
                if pv >= 0:
                    t = sub(c, key[j + 2])
                    if add(t, k0) == pv:
                        push(t, j + 3)
        if not nxt:
            return -100000, None
        states = []
        for s in nxt:
            for r, q in enumerate(states):
                if q[1] == s[1]:
                    if s[0] > q[0]:
                        states[r] = s
                    break
            else:
                if len(states) < 16:
                    states.append(s)
                else:
                    wi = min(range(16), key=lambda r: (states[r][0], r))     # the first worst state
                    if s[0] > states[wi][0]:
                        states[wi] = s
        if abort_at is not None and i + 1 == abort_at and max(q[0] for q in states) < abort_thr:
            return max(q[0] for q in states), None
    best = states[0]
    for q in states[1:]:
        if q[0] > best[0]:
            best = q
    path = None
    if keep_path:
        path, node = [], best[3]
        while node is not None:
            node, p = node
            path.append(p)
        path = path[::-1]
    return best[0], path


# ------------------------------------------------------------------ windows

def make_windows(spec):
    """[(name, previous rune, NR runes)]: `07` = section 0.7 only; `all` = every unsolved section with more than NR runes"""
    import lp
    import stats
    out = []
    for i in stats.UNSOLVED:
        c = lp.runes_of(stats.SEGS[i])
        if (spec == "07" and i != 7) or len(c) < NR + 1:
            continue
        prev = int(lp.runes_of(stats.SEGS[i - 1])[-1]) if i > 7 else -1
        out.append((f"seg0.{i}", prev, np.array(c[:NR])))
    return out


# ------------------------------------------------------------------ GPU

class Sweep:
    def __init__(self, gen, wins, dump=0):
        import cupy as cp
        self.cp, self.gen, self.wins = cp, gen, wins
        defs = {"GEN": GENS[gen], "NW": len(wins), "DUMP": dump}
        src = "".join(f"#define {k} {v}\n" for k, v in defs.items()) + KERNEL.read_text(encoding="utf-8")
        self.kernel = cp.RawModule(code=src, options=NVRTC_OPTIONS).get_function("bg_kernel")
        runes = np.zeros((len(wins), ROW), np.uint8)
        meta = np.zeros((len(wins), 4), np.int32)
        for k, (_, prev, r) in enumerate(wins):
            runes[k, :len(r)] = r
            meta[k] = (prev, len(r), ABORT_AT, ABORT_THR)
        self.d = [cp.asarray(runes.ravel()), cp.asarray(meta.ravel()), cp.asarray(load_table().ravel())]
        self.hist = cp.zeros(HB, cp.uint64)
        self.cand = cp.zeros(2 * CCAP, cp.uint32)
        self.ccount = cp.zeros(1, cp.uint32)

    def launch(self, seed0, n, thr=THR, dump=None):
        cp = self.cp
        self.ccount[:] = 0
        self.kernel(((n + BLOCK - 1) // BLOCK,), (BLOCK,), (
            *self.d, np.uint64(seed0), np.uint64(n), np.int32(thr), self.hist, self.cand, self.ccount, np.uint32(CCAP),
            dump if dump is not None else self.cand.view(cp.int32)))
        cp.cuda.Stream.null.synchronize()
        return int(self.ccount[0])

    def scores(self, lo, n):
        d = self.cp.zeros(n * len(self.wins) * 16, self.cp.int32)
        self.launch(lo, n, 1 << 30, d)
        return d.get().reshape(n, len(self.wins), 16)


def variant_parts(v):
    return (v >> 3) & 1, (v >> 2) & 1, 1 if (v >> 1) & 1 == 0 else -1, v & 1       # model, map, sign, atbash


def mode_sweep(a):
    gen, spec, lo, hi, out = a[0], a[1], int(a[2]), int(a[3]), a[4]
    thr = int(a[5]) if len(a) > 5 else THR
    wins = make_windows(spec)
    S = Sweep(gen, wins)
    info = gpu_common.device_info()
    print(f"bg: {gen} sweep of {hi - lo} seeds, {len(wins)} windows x 16 variants on CUDA {info['name']}", file=sys.stderr, flush=True)
    cand = np.zeros((0, 2), np.uint32)
    hist = np.zeros(HB, np.uint64)
    t_start = last = time.time()
    done, chunk = 0, 1 << 12
    total = hi - lo
    while done < total:
        n = min(chunk, total - done)
        while True:
            S.hist[:] = 0
            t1 = time.time()
            cnt = S.launch(lo + done, n, thr)
            dt = time.time() - t1
            if cnt <= CCAP:
                break
            thr += 25
        hist += S.hist.get()
        if cnt:
            cand = np.concatenate([cand, S.cand[:2 * cnt].get().reshape(cnt, 2)])
            if len(cand) > 4 * TOPK:
                sc = (cand[:, 1] >> 16).astype(np.int64)
                kth = int(np.sort(sc)[-TOPK])
                cand = cand[sc >= kth]
        done += n
        chunk = int(min(max(chunk * min(2.0, TARGET_S / max(dt, 1e-3)), 1 << 8), 1 << 24))
        if time.time() - last >= 20:
            last = time.time()
            el, frac = last - t_start, done / total
            print(f"{100 * frac:.2f}% ({done} seeds) {done / el:.0f} seeds/s, eta {el * (1 - frac) / max(frac, 1e-9):.0f} s", file=sys.stderr, flush=True)
    secs = time.time() - t_start
    order = np.lexsort((cand[:, 1] & 0xFFFF, cand[:, 0], -(cand[:, 1] >> 16).astype(np.int64)))[:TOPK]
    rows = ["score\tseed\twindow\tmodel\tmap\tsign\tatbash"]
    for seed, packed in cand[order]:
        s, wi, v = int(packed) >> 16, (int(packed) >> 8) & 0xFF, int(packed) & 0xFF
        model, mp, sign, atb = variant_parts(v)
        rows.append(f"{s - 2048}\t{int(seed)}\t{wins[wi][0]}\t{model}\t{mp}\t{sign}\t{atb}")
    Path(out).write_text("\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    best = (int(cand[order[0], 1] >> 16) - 2048) if len(order) else None
    print(f"swept {total} seeds in {secs:.0f} s; best score {best}; candidates >= {thr}: {len(cand)}", file=sys.stderr, flush=True)
    print("hist (bins of 20 from -400) " + " ".join(f"{b}:{int(c)}" for b, c in enumerate(hist) if c), file=sys.stderr, flush=True)
    return 0


# ------------------------------------------------------------------ verification of the best candidates

def rust_bin():
    cand = [p for p in (HERE / "target" / "release" / EXE, HERE / "target_gen" / "release" / EXE) if p.exists()]
    return max(cand, key=lambda p: p.stat().st_mtime)


def rust_keys(gen, seed, count):
    with tempfile.TemporaryDirectory() as d:
        out = os.path.join(d, "k.txt")
        subprocess.run([str(rust_bin()), "keysn", gen, str(seed), str(seed + 1), out, "29", str(count)], check=True, capture_output=True)
        v = [int(x) for x in Path(out).read_text().split()]
    return [np.array(v[1:1 + count]), np.array(v[1 + count:])]


def mode_verify(args):
    import lp
    import stats
    tbl = load_table()
    rows = [l.split("\t") for l in Path(args.tsv).read_text(encoding="utf-8").splitlines()[1:] if l.strip()]
    print(f"# boundary-free verification of the best {min(args.top, len(rows))} candidates of {args.gen}: bigram score per rune over the WHOLE section "
          f"(a true key keeps about +10 per rune, a wrong one about -12), against the same decode with 8 random seeds")
    if not rows:
        print("no candidate reached the sweep's floor")
        return 0
    rng = np.random.default_rng(0)
    for score, seed, window, model, mp, sign, atb in rows[:args.top]:
        sec = int(re.match(r"seg0\.(\d+)", window).group(1))
        c = np.array(lp.runes_of(stats.SEGS[sec]))
        prev = int(lp.runes_of(stats.SEGS[sec - 1])[-1]) if sec > 7 else -1
        cnt = 3 * len(c) + 60

        def whole(sd):
            key = rust_keys(args.gen, sd, cnt)[int(mp)]
            s, _ = ref_decode(c, prev, key, int(sign), int(atb), int(model), tbl)
            return s / len(c)

        real = whole(int(seed))
        rnd = [whole(int(x)) for x in rng.integers(0, 2 ** 32, 8)]
        print(f"{score}\tseed {seed}\t{window} model {model} map {mp} sign {sign} atb {atb}: {real:+.2f} per rune over {len(c)} runes "
              f"(random seeds {np.mean(rnd):+.2f} +- {np.std(rnd):.2f})")
    return 0


def main():
    a = sys.argv[1:]
    if a and a[0] == "probe":
        return gpu_common.probe()
    if a and a[0] == "table":
        TABLE.write_text("\n".join(" ".join(map(str, row)) for row in make_table()) + "\n", encoding="utf-8", newline="\n")
        print("wrote data/bigram.txt")
        return 0
    if a and a[0] == "sweep" and len(a) >= 6:
        return mode_sweep(a[1:])
    if a and a[0] == "verify":
        ap = argparse.ArgumentParser()
        ap.add_argument("tsv")
        ap.add_argument("--gen", required=True)
        ap.add_argument("--top", type=int, default=10)
        return mode_verify(ap.parse_args(a[1:]))
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main())
